    if (!output || typeof output !== "object")
      return;
    const record = output;
    if (record.applied === true) {
      this.#renamePlans.delete(sessionID);
      return;
    }
    const { file, old_name: oldName, new_name: newName, others } = record;
    if (typeof file !== "string" || typeof oldName !== "string" || typeof newName !== "string")
      return;
    const files = new Set([path2.resolve(file)]);
    if (Array.isArray(others)) {
      for (const item of others) {
        if (!item || typeof item !== "object")
          continue;
        const otherFile = item.file;
        if (typeof otherFile === "string")
          files.add(path2.resolve(otherFile));
