    this.#renamePlans.set(sessionID, { summary: `${oldName} -> ${newName}`, files });
  }
  render(sessionID) {
    const paths = this.#pathsBySession.get(sessionID);
    const sections = [];
    if (paths?.size) {
      sections.push(`## ReadSeek Anchors
The following files have fresh LINE:HASH anchors:
${[...paths].sort().map((filePath) => `- ${filePath}`).join(`
`)}`);
